      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória no Managed Heap todo frame dentro do Update(). A concatenação iterativa de strings ('s += i.ToString()') gera centenas de strings intermediárias imutáveis descartadas em milissegundos, enquanto a criação de arrays 'new object[10000]' agrava a pressão sobre o Garbage Collector, forçando pausas de coleta de até 21.92ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;
        [Range(1, 20)] public float spawnRadius = 10f;
        [Range(1, 50)] public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)] public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)] public int prepopulateCount = 0;

        private StringBuilder _stringBuilder;
        private object[][] _reusableArrays;
        private MaterialPropertyBlock _propBlock;

        private void Awake()
        {
            _stringBuilder = new StringBuilder(gcConcatIterations * 8);
            _propBlock = new MaterialPropertyBlock();
            if (gcArrayAllocs > 0)
            {
                _reusableArrays = new object[gcArrayAllocs][];
                for (int i = 0; i < gcArrayAllocs; i++)
                {
                    _reusableArrays[i] = new object[10000];
                }
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _stringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _stringBuilder.Append(i);
                }
                GC.KeepAlive(_stringBuilder);
            }

            if (stressCpu)
            {
                // FindObjectsOfType em loop no Update causa gargalo crítico de CPU e aloca arrays managed repetidamente.
                // Manteve-se cacheado/limitado para evitar travamento da main thread.
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var r = clone.GetComponent<Renderer>();
                if (r != null)
                {
                    r.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor("_BaseColor", new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    r.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, o texto (string) é imutável. Toda vez que fazemos 'texto += algo', a Unity cria um pedaço novo de memória e abandona o antigo. Fazer isso milhares de vezes por frame lota a memória gerenciada (Heap) e aciona o 'Garbage Collector' (faxineiro da memória). Quando o faxineiro roda, o jogo congela por vários milissegundos, gerando engasgos (stutter). Utilizar StringBuilder e reutilizar arrays pré-alocados mantém o consumo zerado durante o gameplay."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva a 'GameObject.FindObjectsOfType<GameObject>()' dentro do Update(). Esse método faz uma varredura completa em toda a hierarquia de cena na memória nativa da Unity e gera um novo array managed a cada invocação, consumindo mais de 100ms de CPU por frame no loop.",
      "codigo_refatorado": "using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class CpuOptimizationExample : MonoBehaviour
    {
        // Em vez de buscar todos os objetos a cada frame com FindObjectsOfType,
        // registre os objetos relevantes em listas centralizadas ou use eventos.
        private static readonly System.Collections.Generic.List<GameObject> TrackedObjects = new System.Collections.Generic.List<GameObject>();

        public static void Register(GameObject go) => TrackedObjects.Add(go);
        public static void Unregister(GameObject go) => TrackedObjects.Remove(go);

        private void Update()
        {
            // Itera diretamente sobre a lista já conhecida sem varreduras globais
            int count = TrackedObjects.Count;
            for (int i = 0; i < count; i++)
            {
                var obj = TrackedObjects[i];
                if (obj != null)
                {
                    // Processamento estritamente necessário
                }
            }
        }
    }
}",
      "explicacao_didatica": "O comando 'FindObjectsOfType' é como procurar um arquivo abrindo todas as gavetas do escritório uma por uma. Fazer isso 60 vezes por segundo esgota o processador (CPU). A melhor prática é manter uma lista pronta com os itens importantes, atualizada apenas quando um novo item nasce ou morre na cena."
    }
  ],
  "dicas_level_design": null
}

